class Solution:
    def goodSubsetofBinaryMatrix(self, grid: List[List[int]]) -> List[int]:
        masks = [sum(v << j for j, v in enumerate(row)) for row in grid]
        for i, m in enumerate(masks):
            if m == 0:
                return [i]
        n = len(grid)
        for i in range(n):
            for j in range(i + 1, n):
                if masks[i] & masks[j] == 0:
                    return [i, j]
        return []

