class Solution {
public:
    vector<int> goodSubsetofBinaryMatrix(vector<vector<int>>& grid) {
        int m = grid.size();
        vector<int> masks(m);
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < (int)grid[i].size(); ++j)
                masks[i] |= grid[i][j] << j;
        for (int i = 0; i < m; ++i) if (!masks[i]) return {i};
        for (int i = 0; i < m; ++i)
            for (int j = i + 1; j < m; ++j)
                if (!(masks[i] & masks[j])) return {i, j};
        return {};
    }
};

