class Solution {
    public List<Integer> goodSubsetofBinaryMatrix(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] masks = new int[m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) masks[i] |= grid[i][j] << j;
        for (int i = 0; i < m; i++) if (masks[i] == 0) return List.of(i);
        for (int i = 0; i < m; i++)
            for (int j = i + 1; j < m; j++)
                if ((masks[i] & masks[j]) == 0) return List.of(i, j);
        return List.of();
    }
}

