var goodSubsetofBinaryMatrix = function(grid) {
    const masks = grid.map(r => r.reduce((a, v, j) => a | (v << j), 0));
    for (let i = 0; i < masks.length; i++) if (masks[i] === 0) return [i];
    for (let i = 0; i < masks.length; i++)
        for (let j = i + 1; j < masks.length; j++)
            if ((masks[i] & masks[j]) === 0) return [i, j];
    return [];
};
